// Validation et préparation des données (avec support batch)
// v2.1 - 2026-05-01: Ajout normalizeTraite() pour UPDATE cd.traite
const input = $('Webhook Trigger').first().json;
const body = input.body || input;
const headers = input.headers || {};
const projectId = headers['x-project-id'] || body.project_id || body.projectId || (body.context && body.context.project_id) || null;

const startTime = Date.now();

// ============================================
// NORMALISATION TRAITE (UPDATE cd.traite 2026-05-01)
// 7 patterns couvrant ~95% des cas
// Ref: docs/issues/2026-05-01-update-cd-traite-normalization.md
// À SUPPRIMER quand PR feat(vocalization) Option C sera mergée côté API
// ============================================
function normalizeTraite(input) {
  if (!input) return input;
  let m;
  // Pattern 1: "English Explanation of <X>" → "<X>"
  m = input.match(/^English Explanation of (.+)$/);
  if (m) return m[1];
  // Pattern 2: "Rif <X>" → "<X>"
  m = input.match(/^Rif (.+)$/);
  if (m) return m[1];
  // Pattern 3: "<X>; Alternate Version|Mahadurah Tanina|Second Recension" → "<X>"
  m = input.match(/^(.+); (?:Alternate Version|Mahadurah Tanina|Second Recension)$/);
  if (m) return m[1];
  // Pattern 4: "Mishnah Taanit" → "Mishnah Ta'anit"
  if (input === 'Mishnah Taanit') return "Mishnah Ta'anit";
  // Pattern 5: "Avot" → "Pirkei Avot"
  if (input === 'Avot') return 'Pirkei Avot';
  // Pattern 6: "Mishnah Baba <X>" → "Mishnah Bava <X>"
  m = input.match(/^Mishnah Baba (.+)$/);
  if (m) return `Mishnah Bava ${m[1]}`;
  // Pattern 7: "Jerusalem Talmud, <X>" → "Jerusalem Talmud <X>"
  m = input.match(/^Jerusalem Talmud, (.+)$/);
  if (m) return `Jerusalem Talmud ${m[1]}`;
  // Default: pass-through (déjà canonique)
  return input;
}

// Extraction des paramètres
const openaiApiKey = body.openai_api_key || '';
const context = body.context || {};

// Normaliser traite si présent dans le contexte
const normalizedTraite = context.traite ? normalizeTraite(context.traite) : null;
const traiteWasNormalized = normalizedTraite && normalizedTraite !== context.traite;

// Détecter mode batch ou single
const isBatch = Array.isArray(body.items) && body.items.length > 0;

// Validation
const errors = [];

if (!openaiApiKey || openaiApiKey.trim().length === 0) {
  errors.push('Le champ "openai_api_key" est requis');
}

if (isBatch) {
  // Validation batch
  for (let i = 0; i < body.items.length; i++) {
    const item = body.items[i];
    if (!item.text || item.text.trim().length === 0) {
      errors.push(`Item ${i}: le champ "text" est requis`);
    }
  }
} else {
  // Validation single (existant)
  const text = body.text || '';
  if (!text || text.trim().length === 0) {
    errors.push('Le champ "text" est requis');
  }
}

// === MODE SINGLE (rétrocompatibilité) ===
if (!isBatch) {
  const text = body.text || '';
  const segmentId = body.segment_id || null;
  const sourceTextId = body.source_text_id || null;
  const commentaryId = body.commentary_id || null;

  let cacheSearchParams = '';
  if (segmentId) {
    cacheSearchParams = `segment_id=${segmentId}`;
  } else if (sourceTextId) {
    cacheSearchParams = `source_text_id=${sourceTextId}`;
  } else if (commentaryId) {
    cacheSearchParams = `commentary_id=${commentaryId}`;
  } else if (normalizedTraite && context.page) {
    // Utiliser le traite normalisé pour la recherche cache
    cacheSearchParams = `traite=${encodeURIComponent(normalizedTraite)}&page=${encodeURIComponent(context.page)}`;
    if (context.commentator) {
      cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
    }
  }

  return [{
    json: {
      valid: errors.length === 0,
      errors: errors,
      isBatch: false,
      text: text,
      openaiApiKey: openaiApiKey,
      segmentId: segmentId,
      sourceTextId: sourceTextId,
      commentaryId: commentaryId,
      context: context,
      normalizedTraite: normalizedTraite,
      traiteWasNormalized: traiteWasNormalized,
      startTime: startTime,
      cacheSearchParams: cacheSearchParams,
      canSearchCache: !!(segmentId || sourceTextId || commentaryId || (normalizedTraite && context.page)),
      isCommentary: !!commentaryId
    }
  }];
}

// === MODE BATCH ===
const items = body.items.map((item, index) => ({
  index,
  text: item.text,
  segment_id: item.segment_id || null,
  commentary_id: item.commentary_id || null,
  source_text_id: item.source_text_id || null
}));

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    isBatch: true,
    items: items,
    itemCount: items.length,
    openaiApiKey: openaiApiKey,
    context: context,
    normalizedTraite: normalizedTraite,
    traiteWasNormalized: traiteWasNormalized,
    startTime: startTime,
    projectId: projectId,
    job_id: body.job_id || null
  }
}];

// Vérifier si le cache a retourné une vocalisation
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Cache hit si status 200 et vocalisation trouvée
const cacheHit = statusCode === 200 && data.found === true && data.vocalized_text;

if (cacheHit) {
  return [{
    json: {
      cacheHit: true,
      vocalizedText: data.vocalized_text,
      vocalizedBy: data.vocalized_by || 'cached',
      vocalizedAt: data.vocalized_at,
      // Passer les données pour la réponse
      originalText: prevData.text,
      sourceTextId: data.source_text_id || prevData.sourceTextId,
      commentaryId: data.commentary_id || prevData.commentaryId,
      context: prevData.context,
      startTime: prevData.startTime
    }
  }];
}

// Cache miss - passer au LLM
return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Formater la réponse depuis le cache
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.vocalizedText
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      source_text_id: input.sourceTextId || null,
      commentary_id: input.commentaryId || null,
      vocalized_by: input.vocalizedBy,
      source: 'cache',
      cached_at: input.vocalizedAt,
      processing_time_ms: processingTime
    }
  }
}];

// Extraire la vocalisation et préparer la sauvegarde
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const endTime = Date.now();
const processingTime = endTime - prevData.startTime;

// Gestion fullResponse ou réponse directe
const data = input.body || input;
const statusCode = input.statusCode;

// Vérifier les erreurs de connexion (n8n retourne error.code comme string)
if (input.error && typeof input.error.code === 'string') {
  return [{
    json: {
      success: false,
      error: {
        code: 503,
        message: `Erreur connexion OpenAI: ${input.error.message || input.error.code}`,
        status: 'CONNECTION_ERROR'
      }
    }
  }];
}

// Vérifier les erreurs HTTP (statusCode >= 400 ou data.error avec message)
const hasHttpError = typeof statusCode === 'number' && statusCode >= 400;
const hasApiError = data.error && data.error.message;
if (hasHttpError || hasApiError) {
  const errorMsg = data.error?.message || `Erreur HTTP ${statusCode}`;
  const errorCode = hasHttpError ? statusCode : 500;
  return [{
    json: {
      success: false,
      error: {
        code: errorCode,
        message: `Erreur API OpenAI: ${errorMsg}`,
        status: 'OPENAI_API_ERROR'
      }
    }
  }];
}

// Extraire le texte vocalisé
let vocalizedText = '';
if (data.choices && data.choices[0]?.message?.content) {
  vocalizedText = data.choices[0].message.content.trim();
}

if (!vocalizedText) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Aucune vocalisation retournée par GPT',
        status: 'EMPTY_GPT_RESPONSE'
      }
    }
  }];
}

const usage = data.usage || {};

// Construire la réponse
const response = {
  success: true,
  cached: false,
  vocalization: {
    original: prevData.text,
    vocalized: vocalizedText
  },
  metadata: {
    traite: prevData.context.traite || null,
    page: prevData.context.page || null,
    commentator: prevData.context.commentator || null,
    segment_id: prevData.segmentId || null,
    source_text_id: prevData.sourceTextId || null,
    commentary_id: prevData.commentaryId || null,
    vocalized_by: 'llm:gpt-4o',
    model: 'gpt-4o',
    source: 'generated',
    processing_time_ms: processingTime,
    tokens: {
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0
    }
  },
  // Données pour sauvegarde
  _saveData: {
    segment_id: prevData.segmentId || null,
    source_text_id: prevData.sourceTextId || null,
    commentary_id: prevData.commentaryId || null,
    vocalized_text: vocalizedText,
    vocalized_by: 'llm:gpt-4o'
  }
};

return [{ json: response }];

// Nettoyer la réponse (supprimer _saveData)
const prevResponse = $('Extract GPT Response').first().json;

// Supprimer les données internes
const response = { ...prevResponse };
delete response._saveData;

return [{ json: response }];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Vérifier si le commentaire a des nekudot
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode;

// Si erreur de connexion (error.code est une string comme 'ERR_BAD_REQUEST')
if (input.error && typeof input.error.code === 'string') {
  return [{
    json: {
      hasNekudot: false,
      ...prevData
    }
  }];
}

// Si erreur HTTP, passer à la vocalisation
if (typeof statusCode === 'number' && statusCode >= 400) {
  return [{
    json: {
      hasNekudot: false,
      ...prevData
    }
  }];
}

// Vérifier si les nekudot existent
const nekudot = data.nekudot || {};
const nekudotData = nekudot[prevData.commentaryId];

if (nekudotData && nekudotData.text) {
  return [{
    json: {
      hasNekudot: true,
      cachedNekudot: nekudotData.text,
      cachedAt: nekudotData.vocalized_at,
      originalText: prevData.text,
      context: prevData.context,
      startTime: prevData.startTime,
      commentaryId: prevData.commentaryId
    }
  }];
}

// Pas de nekudot, passer à GPT-4o
return [{
  json: {
    hasNekudot: false,
    ...prevData
  }
}];

// Formater la réponse pour les nekudot depuis la BDD
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.cachedNekudot
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      commentary_id: input.commentaryId,
      vocalized_by: 'database',
      source: 'database',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    }
  }
}];

// Préparer les items pour le traitement en boucle
const data = $input.first().json;

return data.items.map(item => ({
  json: {
    index: item.index,
    text: item.text,
    commentary_id: item.commentary_id,
    source_text_id: item.source_text_id,
    openaiApiKey: data.openaiApiKey,
    context: data.context,
    startTime: data.startTime,
    // Construire les paramètres de recherche cache
    cacheSearchParams: item.commentary_id 
      ? `commentary_id=${item.commentary_id}` 
      : (item.source_text_id ? `source_text_id=${item.source_text_id}` : ''),
    canSearchCache: !!(item.commentary_id || item.source_text_id),
    isCommentary: !!item.commentary_id
  }
}));

// Préparer l'item courant pour traitement (cache ou GPT)
const item = $input.first().json;

return [{
  json: {
    valid: true,
    text: item.text,
    openaiApiKey: item.openaiApiKey,
    sourceTextId: item.source_text_id,
    commentaryId: item.commentary_id,
    context: item.context,
    startTime: item.startTime,
    cacheSearchParams: item.cacheSearchParams,
    canSearchCache: item.canSearchCache,
    isCommentary: item.isCommentary,
    // Garder l'index pour le merge
    _batchIndex: item.index
  }
}];

// Collecter le résultat pour cet item
const result = $input.first().json;
const batchIndex = $('Process Batch Item').first().json._batchIndex;
const itemData = $('Process Batch Item').first().json;

return [{
  json: {
    index: batchIndex,
    commentary_id: itemData.commentaryId,
    source_text_id: itemData.sourceTextId,
    vocalization: result.vocalization || null,
    cached: result.cached || false,
    success: result.success !== false,
    error: result.error || null
  }
}];

// Merger tous les résultats batch
const allResults = $input.all().map(item => item.json);
const startTime = $('Validate Input').first().json.startTime;

const endTime = Date.now();
const processingTime = endTime - startTime;

// Trier par index
allResults.sort((a, b) => a.index - b.index);

// Calculer les stats
const total = allResults.length;
const cached = allResults.filter(r => r.cached).length;
const generated = allResults.filter(r => !r.cached && r.success).length;
const errorsCount = allResults.filter(r => !r.success).length;

// Nettoyer les résultats (enlever l'index interne)
const cleanResults = allResults.map(r => ({
  commentary_id: r.commentary_id,
  source_text_id: r.source_text_id,
  vocalization: r.vocalization,
  cached: r.cached,
  success: r.success,
  error: r.error
}));

return [{
  json: {
    success: errorsCount < total,  // Au moins un succès
    results: cleanResults,
    summary: {
      total: total,
      cached: cached,
      generated: generated,
      errors: errorsCount,
      processing_time_ms: processingTime
    }
  }
}];

