    vocalized: vocalizedText
  },
  metadata: {
    traite: prevData.context.traite || null,
    page: prevData.context.page || null,
    commentator: prevData.context.commentator || null,
    segment_id: prevData.segmentId || null,
    source_text_id: prevData.sourceTextId || null,
    commentary_id: prevData.commentaryId || null,
    vocalized_by: 'llm:gpt-4o',
    model: 'gpt-4o',
    source: 'generated',
    processing_time_ms: processingTime,
    tokens: {
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0
    }
  },
  // Données pour sauvegarde
  _saveData: {
    segment_id: prevData.segmentId || null,
    source_text_id: prevData.sourceTextId || null,
    commentary_id: prevData.commentaryId || null,
    vocalized_text: vocalizedText,
    vocalized_by: 'llm:gpt-4o'
  }
};

return [{ json: response }];

// Nettoyer la réponse (supprimer _saveData)
const prevResponse = $('Extract GPT Response').first().json;

// Supprimer les données internes
const response = { ...prevResponse };
delete response._saveData;

return [{ json: response }];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Vérifier si le commentaire a des nekudot
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode;

// Si erreur de connexion (error.code est une string comme 'ERR_BAD_REQUEST')
if (input.error && typeof input.error.code === 'string') {
  return [{
    json: {
      hasNekudot: false,
      ...prevData
    }
  }];
}

// Si erreur HTTP, passer à la vocalisation
if (typeof statusCode === 'number' && statusCode >= 400) {
  return [{
    json: {
      hasNekudot: false,
      ...prevData
    }
  }];
}

// Vérifier si les nekudot existent
const nekudot = data.nekudot || {};
const nekudotData = nekudot[prevData.commentaryId];

if (nekudotData && nekudotData.text) {
  return [{
    json: {
      hasNekudot: true,
      cachedNekudot: nekudotData.text,
      cachedAt: nekudotData.vocalized_at,
      originalText: prevData.text,
      context: prevData.context,
      startTime: prevData.startTime,
      commentaryId: prevData.commentaryId
    }
  }];
}

// Pas de nekudot, passer à GPT-4o
return [{
  json: {
    hasNekudot: false,
    ...prevData
  }
}];

// Formater la réponse pour les nekudot depuis la BDD
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.cachedNekudot
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      commentary_id: input.commentaryId,
      vocalized_by: 'database',
      source: 'database',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    }
  }
}];

// Préparer les items pour le traitement en boucle
const data = $input.first().json;

return data.items.map(item => ({
  json: {
    index: item.index,
    text: item.text,
    commentary_id: item.commentary_id,
    source_text_id: item.source_text_id,
    openaiApiKey: data.openaiApiKey,
    context: data.context,
    startTime: data.startTime,
    // Construire les paramètres de recherche cache
    cacheSearchParams: item.commentary_id 
      ? `commentary_id=${item.commentary_id}` 
      : (item.source_text_id ? `source_text_id=${item.source_text_id}` : ''),
    canSearchCache: !!(item.commentary_id || item.source_text_id),
    isCommentary: !!item.commentary_id
  }
}));

// Préparer l'item courant pour traitement (cache ou GPT)
const item = $input.first().json;

return [{
  json: {
    valid: true,
    text: item.text,
    openaiApiKey: item.openaiApiKey,
    sourceTextId: item.source_text_id,
    commentaryId: item.commentary_id,
    context: item.context,
    startTime: item.startTime,
    cacheSearchParams: item.cacheSearchParams,
    canSearchCache: item.canSearchCache,
    isCommentary: item.isCommentary,
    // Garder l'index pour le merge
    _batchIndex: item.index
  }
}];

// Collecter le résultat pour cet item
const result = $input.first().json;
const batchIndex = $('Process Batch Item').first().json._batchIndex;
const itemData = $('Process Batch Item').first().json;

return [{
  json: {
    index: batchIndex,
    commentary_id: itemData.commentaryId,
    source_text_id: itemData.sourceTextId,
    vocalization: result.vocalization || null,
    cached: result.cached || false,
    success: result.success !== false,
    error: result.error || null
  }
}];

// Merger tous les résultats batch
const allResults = $input.all().map(item => item.json);
const startTime = $('Validate Input').first().json.startTime;

const endTime = Date.now();
const processingTime = endTime - startTime;

// Trier par index
allResults.sort((a, b) => a.index - b.index);

// Calculer les stats
const total = allResults.length;
const cached = allResults.filter(r => r.cached).length;
const generated = allResults.filter(r => !r.cached && r.success).length;
const errorsCount = allResults.filter(r => !r.success).length;

// Nettoyer les résultats (enlever l'index interne)
const cleanResults = allResults.map(r => ({
  commentary_id: r.commentary_id,
  source_text_id: r.source_text_id,
  vocalization: r.vocalization,
  cached: r.cached,
  success: r.success,
  error: r.error
}));

return [{
  json: {
    success: errorsCount < total,  // Au moins un succès
    results: cleanResults,
    summary: {
      total: total,
      cached: cached,
      generated: generated,
      errors: errorsCount,
      processing_time_ms: processingTime
    }
  }
}];

